modules.game.rng:
local M = {}

function M.new(seed)
	local self = { state = math.floor(tonumber(seed) or 1337) % 2147483647 }
	if self.state <= 0 then self.state = self.state + 2147483646 end

	function self:next()
		self.state = (self.state * 48271) % 2147483647
		return (self.state - 1) / 2147483646
	end

	function self:range(a, b)
		return a + (b - a) * self:next()
	end

	function self:int(a, b)
		return math.floor(self:range(a, b + 1))
	end

	function self:pick(values)
		return values[self:int(1, #values)]
	end

	return self
end

return M
